import{_ as t,o as n,c as d,a2 as r}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"Was bedeuten die Meldungen im Adapter-Log?","description":"","frontmatter":{"order":6,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/03.referenz/06.log-meldungen.md"},"headers":[],"relativePath":"de/adapter/esphome/referenz/log-meldungen.md","filePath":"de/adapter/esphome/referenz/log-meldungen.md","lastUpdated":1795562976000}'),i={name:"de/adapter/esphome/referenz/log-meldungen.md"};function a(s,e,o,l,c,h){return n(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="was-bedeuten-die-meldungen-im-adapter-log" tabindex="-1">Was bedeuten die Meldungen im Adapter-Log? <a class="header-anchor" href="#was-bedeuten-die-meldungen-im-adapter-log" aria-label="Permalink to &quot;Was bedeuten die Meldungen im Adapter-Log?&quot;">​</a></h1><p><a id="log-full-errors-connections-drop"></a></p><h2 id="warum-ist-das-log-voll-mit-fehlern-bei-verbindungsabbruchen-und-reconnects" tabindex="-1">Warum ist das Log voll mit Fehlern bei Verbindungsabbrüchen und Reconnects? <a class="header-anchor" href="#warum-ist-das-log-voll-mit-fehlern-bei-verbindungsabbruchen-und-reconnects" aria-label="Permalink to &quot;Warum ist das Log voll mit Fehlern bei Verbindungsabbrüchen und Reconnects?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="deserializebinary-assertion-failed-bad-format"></a></p><h2 id="was-bedeuten-deserializebinary-assertion-failed-bad-format-und-invalid-wire-type" tabindex="-1">Was bedeuten &quot;deserializeBinary&quot;, &quot;Assertion failed&quot;, &quot;Bad format&quot; und &quot;Invalid wire type&quot;? <a class="header-anchor" href="#was-bedeuten-deserializebinary-assertion-failed-bad-format-und-invalid-wire-type" aria-label="Permalink to &quot;Was bedeuten &quot;deserializeBinary&quot;, &quot;Assertion failed&quot;, &quot;Bad format&quot; und &quot;Invalid wire type&quot;?&quot;">​</a></h2><p>Diese Meldungen kommen aus der Bibliothek, über die der Adapter mit dem Gerät spricht (<code>@2colors/esphome-native-api</code>). Sie bedeuten, dass Adapter und Gerät nicht zusammenpassen, meist beim Verschlüsselungsschlüssel, seltener weil die Firmware Nachrichten schickt, die die Bibliothek nicht kennt.</p><p>Einen fehlenden Schlüssel, ein falsches API-Passwort und Netzwerkfehler übersetzt der Adapter in eigene Meldungen. Alle anderen Fehler stehen unverändert als <code>ESPHome client &lt;IP&gt; &lt;Fehler&gt;</code> im Log, bei jedem Verbindungsversuch wieder.</p><table tabindex="0"><thead><tr><th>Meldung im Log</th><th>Was dahintersteckt</th><th>Was du tust</th></tr></thead><tbody><tr><td><code>Device &lt;IP&gt; requires an encryption key</code></td><td>Das Gerät nutzt Verschlüsselung, im Adapter fehlt der Schlüssel.</td><td>Schlüssel aus <code>api:</code> → <code>encryption:</code> → <code>key:</code> beim Gerät eintragen.</td></tr><tr><td><code>Bad format. Expected 1 at the begin</code></td><td>Im Adapter steht ein Schlüssel, das Gerät antwortet unverschlüsselt.</td><td>Verschlüsselung in der YAML einschalten und neu flashen, oder den Schlüssel im Adapter entfernen.</td></tr><tr><td><code>Bad format. Expected 0 at the begin</code></td><td>Unter der Adresse antwortet etwas anderes als die ESPHome-API.</td><td>Prüfen, ob unter der Adresse wirklich das Gerät läuft.</td></tr><tr><td><code>Handshake failure</code></td><td>Das Gerät hat den Schlüssel abgelehnt.</td><td>Schlüssel in YAML und Adapter Zeichen für Zeichen vergleichen.</td></tr><tr><td><code>Failed find or parsed message type for Id: &lt;Nummer&gt;</code></td><td>Die Bibliothek konnte eine Nachricht des Geräts nicht lesen und trennt die Verbindung.</td><td>Schritte unten.</td></tr><tr><td><code>deserializeBinary</code>, <code>Assertion failed</code>, <code>Invalid wire type</code></td><td>Dieselbe Ursache wie die Zeile darüber.</td><td>Schritte unten.</td></tr></tbody></table><h3 id="so-gehst-du-vor" tabindex="-1">So gehst du vor <a class="header-anchor" href="#so-gehst-du-vor" aria-label="Permalink to &quot;So gehst du vor&quot;">​</a></h3><ol><li>Prüfe, dass die YAML des Geräts einen Abschnitt <code>api:</code> hat. Ohne ihn kann der Adapter nicht mit dem Gerät sprechen.</li><li>Vergleiche den Schlüssel unter <code>api:</code> → <code>encryption:</code> → <code>key:</code> mit dem im Adapter. Öffne dazu im Reiter „Geräte“ beim Gerät „Verbindungseinstellungen ändern“. Hat das Gerät keine Verschlüsselung, muss das Feld leer sein.</li><li>Hast du die Firmware gerade auf eine neue ESPHome-Version gebracht, kennt die Bibliothek ihre Nachrichten eventuell noch nicht. Dann hilft eine neuere Adapter-Version oder vorerst die ältere Firmware.</li><li>Kommt die Meldung weiter, lösch das Gerät im Reiter „Geräte“ und füge es mit Adresse und Schlüssel neu hinzu.</li><li>Geklappt hat es, wenn im Log <code>ESPHome client &lt;IP&gt; connected</code> steht und <code>esphome.0.&lt;Gerät&gt;.info._online</code> auf <code>true</code> geht.</li></ol><p>Ein Gerät, das auf Ping antwortet, kann für den Adapter trotzdem offline sein. Der Ping prüft nur das Netzwerk, diese Meldungen betreffen die ESPHome-API auf Port 6053.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erstes-geraet#encryption-key-not-accepted">Warum wird mein Verschlüsselungsschlüssel nicht akzeptiert?</a> · <a href="./../erste-schritte/erstes-geraet#api-password-still-work-esphome">API-Passwort und ESPHome 2026.1</a> · <a href="./../anleitungen/geraete-verwalten#delete-device-completely-objects-come">Gerät komplett löschen</a> · <a href="./einstellungen#reconnect-settings-exist-happens-device">Reconnect-Einstellungen</a></p><p><a id="constantly-see-adapter-connections-device"></a></p><h2 id="warum-sehe-ich-im-gerate-log-standig-verbindungen-des-adapters" tabindex="-1">Warum sehe ich im Geräte-Log ständig Verbindungen des Adapters? <a class="header-anchor" href="#warum-sehe-ich-im-gerate-log-standig-verbindungen-des-adapters" aria-label="Permalink to &quot;Warum sehe ich im Geräte-Log ständig Verbindungen des Adapters?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p>',16)])])}const g=t(i,[["render",a]]);export{m as __pageData,g as default};
